 function itemModal(x){let m=modal(x?"Edit Master Item":"Add Master Item",`<div class="formgrid"><div class="field"><label>Row ID</label><input id="eRow" value="${esc(x?.rowId||"")}" placeholder="Auto"></div><div class="field"><label>Name</label><input id="eName" value="${esc(x?.name||"")}"></div><div class="field"><label>SKU</label><input id="eSku" value="${esc(x?.sku||"")}"></div><div class="field"><label>Storage Unit</label><input id="eSU" value="${esc(x?.storageUnit||"")}" placeholder="KG, BATCH, L, PKT"></div><div class="field"><label>Ingredient Unit</label><input id="eIU" value="${esc(x?.ingredientUnit||"")}" placeholder="GRAM, ML, PCS"></div><div class="field"><label>Supplier</label><select id="eSup"><option value="">—</option>${ss.map(s=>`<option ${x?.supplier===s.name?"selected":""}>${esc(s.name)}</option>`).join("")}</select></div><div class="field"><label>Items Type</label><select id="eType">${["BAR","KITCHEN","PASTRY","PACKAGING"].map(t=>`<option ${x?.itemsType?.toUpperCase()===t?"selected":""}>${t}</option>`).join("")}</select></div></div>`,`<div class="actions" style="margin-top:18px;justify-content:flex-end"><button class="btn primary" id="saveItem">Save</button></div>`);m.querySelector("#saveItem").onclick=async()=>{let obj={rowId:m.querySelector("#eRow").value,name:m.querySelector("#eName").value.trim(),sku:m.querySelector("#eSku").value.trim(),storageUnit:m.querySelector("#eSU").value.trim(),ingredientUnit:m.querySelector("#eIU").value.trim(),supplier:m.querySelector("#eSup").value,itemsType:m.querySelector("#eType").value};if(!obj.name||!obj.sku)return toast("Name and SKU are required","error");try{let d=await apiCall("saveEntity",{sheet:"Master_Items",rowId:x?.rowId||null,row:obj});DB.master=d.master;saveJSON(LS.data,DB);m.remove();toast("Master item saved","good");items()}catch(e){toast(e.message,"error")}}}
 function supplierModal(x){let m=modal(x?"Edit Supplier":"Add Supplier",`<div class="formgrid"><div class="field full"><label>Name</label><input id="sName" value="${esc(x?.name||"")}"></div><div class="field"><label>Phone (optional)</label><input id="sPhone" value="${esc(x?.phone||"")}"></div><div class="field"><label>Group Link (optional)</label><input id="sLink" value="${esc(x?.groupLink||"")}"></div><div class="field full"><label>Remarks / Notes</label><textarea id="sRem">${esc(x?.remarks||"")}</textarea></div></div>`,`<div class="actions" style="margin-top:18px;justify-content:flex-end"><button class="btn primary" id="saveSup">Save</button></div>`);m.querySelector("#saveSup").onclick=async()=>{let row={name:m.querySelector("#sName").value.trim(),phone:m.querySelector("#sPhone").value.trim(),groupLink:m.querySelector("#sLink").value.trim(),remarks:m.querySelector("#sRem").value.trim()};if(!row.name)return toast("Supplier name is required","error");try{let d=await apiCall("saveEntity",{sheet:"Suppliers",rowId:x?.rowId||null,row});DB.suppliers=d.suppliers;saveJSON(LS.data,DB);m.remove();toast("Supplier saved","good");items()}catch(e){toast(e.message,"error")}}}
