 function internal(){let rows=db().internal||[];$("#adminView").innerHTML=head("Internal Items","Items available to staff for Production and Wastage",`<button class="btn primary" id="addInternal">+ Add Item</button>`)+`<div class="card"><div class="tablewrap"><table class="table"><thead><tr><th>Row ID</th><th>Name</th><th>SKU</th><th>Storage Unit</th><th>Ingredient Unit</th><th>Items Type</th><th>Actions</th></tr></thead><tbody>${rows.map((x,i)=>`<tr><td>${esc(x.rowId)}</td><td>${esc(x.name)}</td><td>${esc(x.sku)}</td><td>${esc(x.storageUnit)}</td><td>${esc(x.ingredientUnit)}</td><td>${esc(x.itemsType)}</td><td><button class="btn sm" data-ie="${i}">Edit</button> <button class="btn danger sm" data-id="${i}">Delete</button></td></tr>`).join("")}</tbody></table></div></div>`;$("#addInternal").onclick=()=>internalModal();document.querySelectorAll("[data-ie]").forEach(b=>b.onclick=()=>internalModal(rows[+b.dataset.ie]));document.querySelectorAll("[data-id]").forEach(b=>b.onclick=async()=>{if(confirm("Delete this internal item?")){try{let d=await apiCall("deleteRows",{sheet:"Internal_Items",ids:[rows[+b.dataset.id].rowId]});DB.internal=d.internal;saveJSON(LS.data,DB);toast("Deleted","good");internal()}catch(e){toast(e.message,"error")}}})}
